/**
 * The DATABOOK manifest: every series the universe should contain, with its
 * frozen name, metadata, and locator in the 2025 edition. Generated by
 * `propose()` from the 2025 IR, checked into the repo (one JSON file per
 * section under ./manifest/), reviewed, then written to the database by
 * `apply.ts`. Re-running `propose()` with the previous manifest keeps every
 * existing name — names are frozen once assigned (plan §2.2).
 */
import { assignGeographies, type AssignedCell } from "./geoassign";
import type { EditionIR, IRCell, IRTable } from "./ir";
import { labelKey } from "./labels";
import {
  basisNote,
  formatDecimals,
  inferUnit,
  isPercentFormat,
  sourceAgency,
  titleCase,
  type UnitGuess,
} from "./meta";
import { describe, portalNames } from "./naming";
import { panelIdentities } from "./panels";

export const DATABOOK_SOURCE = "DBEDT State of Hawaii Data Book";
export const DATABOOK_URL = "https://dbedt.hawaii.gov/economic/databook/";

export const SECTION_NAMES: Record<number, string> = {
  1: "Population",
  2: "Vital Statistics and Health",
  3: "Education",
  4: "Law Enforcement, Courts, and Prisons",
  5: "Geography and Environment",
  6: "Land Use and Ownership",
  7: "Recreation and Travel",
  8: "Elections",
  9: "Government Finances and Employment",
  10: "National Defense",
  11: "Social Insurance and Human Services",
  12: "Labor Force, Employment, and Earnings",
  13: "Income, Expenditures, and Wealth",
  14: "Prices",
  15: "Banking, Insurance, and Business Enterprise",
  16: "Information and Communications",
  17: "Energy and Science",
  18: "Transportation",
  19: "Agriculture",
  20: "Forests, Fisheries, and Mining",
  21: "Construction and Housing",
  22: "Manufactures",
  23: "Domestic Trade and Services",
  24: "Foreign and Interstate Commerce",
};

export interface SeriesLocator {
  panel: number;
  rowPath: string[];
  colPath: string[];
}

export interface ManifestSeries {
  /** Frozen series name, e.g. "DB0106@HON.A". */
  name: string;
  geo: string;
  /** Where the series lives in the 2025 edition (all cells share it). */
  locator: SeriesLocator;
  /** Came from a single-period snapshot table (needs ≥5 editions to load). */
  snapshot: boolean;
  /** Number of editions this series was matched in — set by `match`. */
  editions?: number;
  /** Distinct observation dates across all editions — set by `match`. */
  observations?: number;
  /** Fill interior gaps with a linear pseudo-history loader — set by `match`. */
  interpolate?: boolean;
}

export interface ManifestMeasurement {
  prefix: string;
  /** Identity within the table: [panel, rowDims, colDims] label keys. */
  key: string;
  /**
   * The measurement's labels with geography taken out, as the base
   * edition prints them: the extract's panel / row / column dimensions.
   */
  dims: { panel: string; row: string[]; column: string[] };
  dataPortalName: string;
  description: string;
  unit: UnitGuess;
  percent: boolean;
  decimals: number;
  /** data_list_measurements indent, 0–3. */
  indent: number;
  /** Footnote markers on this measurement's cells (texts live on the table). */
  footnoteMarkers: string[];
  series: ManifestSeries[];
}

export interface ManifestTable {
  /** Table number in the 2025 edition — also the table-lineage id. */
  tableNum: string;
  title: string;
  titlePeriod: string;
  layout: IRTable["layout"];
  headnote: string;
  footnotes: Record<string, string>;
  /**
   * `agency`/`link` are the DBEDT Data Book itself — that is where udaman
   * gets the data, and citing it keeps users from thinking UHERO compiled
   * the tables. `detail` carries the table number and DBEDT's own citation
   * of the original source; `original*` keep that agency/URL for reference.
   */
  source: {
    agency: string;
    link: string | null;
    detail: string;
    originalAgency: string;
    originalLink: string | null;
  };
  measurements: ManifestMeasurement[];
}

export interface ManifestSection {
  section: number;
  name: string;
  narrative: string;
  tables: ManifestTable[];
}

// ─── Proposal ───────────────────────────────────────────────────────

function colLetter(cellAddr: string): string {
  const m = cellAddr.match(/!\$?([A-Z]+)\$?\d+$/);
  return m ? m[1] : "";
}

interface Draft {
  key: string;
  panel: number;
  panelLabel: string;
  rowDims: string[];
  colDims: string[];
  firstCol: string;
  cells: AssignedCell[];
}

export interface ProposeOptions {
  narratives?: Record<number, string>;
  previous?: ManifestSection[];
}

/** Build the manifest from the 2025 edition IR. */
export function propose(
  ir: EditionIR,
  opts: ProposeOptions = {},
): ManifestSection[] {
  const previousPrefix = new Map<string, string>();
  for (const sec of opts.previous ?? []) {
    for (const t of sec.tables) {
      for (const m of t.measurements) {
        previousPrefix.set(`${t.tableNum}|${m.key}`, m.prefix);
      }
    }
  }

  const cellsByTable = new Map<string, IRCell[]>();
  for (const c of ir.cells) {
    let list = cellsByTable.get(c.tableNum);
    if (!list) cellsByTable.set(c.tableNum, (list = []));
    list.push(c);
  }

  const sections = new Map<number, ManifestSection>();
  const usedPrefixes = new Set<string>();
  for (const table of [...ir.tables].sort((a, b) =>
    a.tableNum.localeCompare(b.tableNum),
  )) {
    if (!["long", "wide", "snapshot"].includes(table.layout)) continue;
    const cells = cellsByTable.get(table.tableNum) ?? [];
    if (cells.length === 0) continue;
    const mt = proposeTable(table, cells, previousPrefix, usedPrefixes);
    if (mt.measurements.length === 0) continue;
    let sec = sections.get(table.section);
    if (!sec) {
      sections.set(
        table.section,
        (sec = {
          section: table.section,
          name: SECTION_NAMES[table.section] ?? `Section ${table.section}`,
          narrative: opts.narratives?.[table.section] ?? "",
          tables: [],
        }),
      );
    }
    sec.tables.push(mt);
  }
  return [...sections.values()].sort((a, b) => a.section - b.section);
}

function proposeTable(
  table: IRTable,
  cells: IRCell[],
  previousPrefix: Map<string, string>,
  usedPrefixes: Set<string>,
): ManifestTable {
  const idents = panelIdentities(table);
  const identOf = (c: IRCell) =>
    idents.get(c.panel) ?? { id: c.panel, label: "" };
  // Geography is taken out of every label; what remains identifies the
  // metric. Panels that differ only by geography ("County" / "Island")
  // therefore share measurements.
  const assigned = assignGeographies(cells, (c) => identOf(c).label, {
    title: table.title,
  });
  const nsOf = splitConflictingPanels(assigned, (c) => identOf(c));
  const namespaceId = new Map<string, number>();
  const drafts = new Map<string, Draft>();
  for (const a of assigned) {
    const ns = nsOf(a);
    const nsId = namespaceId.get(ns) ?? identOf(a.cell).id;
    namespaceId.set(ns, nsId);
    const key = JSON.stringify([
      ns,
      a.rowDims.map(labelKey),
      a.colDims.map(labelKey),
    ]);
    let d = drafts.get(key);
    if (!d) {
      drafts.set(
        key,
        (d = {
          key,
          panel: nsId,
          panelLabel:
            ns === labelKey(a.panelDim) ? a.panelDim : identOf(a.cell).label,
          rowDims: a.rowDims,
          colDims: a.colDims,
          firstCol: colLetter(a.cell.cellAddr),
          cells: [],
        }),
      );
    }
    d.cells.push(a);
  }

  // Prefixes: DB{SSTT}[P{n}][R{nn}][{col letter}], col letter only when needed.
  const base = `DB${table.tableNum.replace(".", "")}`;
  const rowOrdinal = new Map<string, number>();
  const groupOf = (d: Draft) => {
    const p = d.panel > 0 ? `P${d.panel + 1}` : "";
    if (d.rowDims.length === 0) return `${base}${p}`;
    const rk = `${d.panel}|${JSON.stringify(d.rowDims.map(labelKey))}`;
    if (!rowOrdinal.has(rk)) {
      const n =
        [...rowOrdinal.keys()].filter((k) => k.startsWith(`${d.panel}|`))
          .length + 1;
      rowOrdinal.set(rk, n);
    }
    return `${base}${p}R${String(rowOrdinal.get(rk)).padStart(2, "0")}`;
  };
  const groups = new Map<string, Draft[]>();
  for (const d of drafts.values()) {
    const g = groupOf(d);
    groups.set(g, [...(groups.get(g) ?? []), d]);
  }
  const prefixOf = new Map<Draft, string>();
  for (const [g, ds] of groups) {
    if (ds.length === 1) {
      prefixOf.set(ds[0], g);
      continue;
    }
    const seen = new Map<string, number>();
    for (const d of ds) {
      let p = `${g}${d.firstCol}`;
      const n = seen.get(p) ?? 0;
      seen.set(p, n + 1);
      if (n > 0) p = `${p}${n + 1}`;
      prefixOf.set(d, p);
    }
  }

  const title = titleCase(table.title);
  const draftList = [...drafts.values()];
  const rowHeader = (d: Draft) =>
    table.panels.find((p) => p.index === d.panel)?.headers[0]?.[0] ?? "";
  const portals = portalNames(
    draftList.map((d) => ({ ...d, rowHeader: rowHeader(d) })),
    table.title,
  );
  const measurements: ManifestMeasurement[] = [];
  for (const [di, d] of draftList.entries()) {
    let prefix =
      previousPrefix.get(`${table.tableNum}|${d.key}`) ?? prefixOf.get(d)!;
    while (usedPrefixes.has(prefix)) prefix = `${prefix}X`;
    usedPrefixes.add(prefix);

    const parts = [d.panelLabel, ...d.rowDims, ...d.colDims].filter(Boolean);
    const cellsOnly = d.cells.map((a) => a.cell);
    const numFmt = majority(
      cellsOnly.map((c) => c.numFmt).filter((f): f is string => !!f),
    );
    const percent = isPercentFormat(numFmt);
    const decimals = formatDecimals(numFmt) ?? guessDecimals(cellsOnly);
    const basis = basisNote(cellsOnly);
    const portal = portals[di];
    const description = describe(table.title, d, basis);
    const footnoteMarkers = [
      ...new Set(cellsOnly.flatMap((c) => c.markers)),
    ].filter((m) => table.footnotes[m]);

    const series = new Map<string, ManifestSeries>();
    // One label group per geography: if two groups resolve to the same
    // geography (e.g. "State total" in both a County and an Island panel),
    // the first one wins.
    for (const a of d.cells) {
      if (series.has(a.geo)) continue;
      series.set(a.geo, {
        name: `${prefix}@${a.geo}.A`,
        geo: a.geo,
        locator: {
          panel: identOf(a.cell).id,
          rowPath: a.cell.rowPath,
          colPath: a.cell.colPath,
        },
        snapshot: table.layout === "snapshot",
      });
    }

    measurements.push({
      prefix,
      key: d.key,
      dims: { panel: d.panelLabel, row: d.rowDims, column: d.colDims },
      dataPortalName: portal,
      description,
      unit: inferUnit({
        headnote: table.headnote,
        labels: parts,
        title: table.title,
        numFmt,
        percent,
      }),
      percent,
      decimals,
      indent:
        table.layout === "long"
          ? 0
          : Math.min(3, Math.max(0, d.rowDims.length - 1)),
      footnoteMarkers,
      series: [...series.values()],
    });
  }

  return {
    tableNum: table.tableNum,
    title,
    titlePeriod: table.titlePeriod,
    layout: table.layout,
    headnote: table.headnote,
    footnotes: table.footnotes,
    source: {
      agency: DATABOOK_SOURCE,
      link: DATABOOK_URL,
      detail: truncate(
        `Data Book Table ${Number(table.tableNum.slice(0, 2))}.${table.tableNum.slice(3)} (${table.edition} edition). Original source: ${table.source
          .replace(/^\s*sources?:\s*/i, "")
          .replace(/\s+/g, " ")
          .trim()}`,
        1000,
      ),
      originalAgency: sourceAgency(table.source),
      originalLink: table.sourceUrl,
    },
    measurements,
  };
}

/**
 * Panels merge into one measurement when their labels differ only by
 * geography or period ("Year" / "County: 2024"). If two such panels then
 * give the same geography different values for the same date, they are
 * not the same metric after all ("Calendar year" / "Fiscal year"): keep
 * those panels' own labels apart.
 */
function splitConflictingPanels(
  assigned: AssignedCell[],
  identOf: (c: IRCell) => { id: number; label: string },
): (a: AssignedCell) => string {
  const baseKey = (a: AssignedCell) =>
    JSON.stringify([
      labelKey(a.panelDim),
      a.rowDims.map(labelKey),
      a.colDims.map(labelKey),
      a.geo,
    ]);
  // key → date → panel id → value
  const seen = new Map<string, Map<string, Map<number, number>>>();
  const split = new Set<number>();
  for (const a of assigned) {
    if (!a.cell.period.date) continue;
    const k = baseKey(a);
    let byDate = seen.get(k);
    if (!byDate) seen.set(k, (byDate = new Map()));
    let byPanel = byDate.get(a.cell.period.date);
    if (!byPanel) byDate.set(a.cell.period.date, (byPanel = new Map()));
    const id = identOf(a.cell).id;
    for (const [other, v] of byPanel) {
      if (other !== id && v !== a.cell.value) {
        split.add(other);
        split.add(id);
      }
    }
    byPanel.set(id, a.cell.value);
  }
  return (a) => {
    const ident = identOf(a.cell);
    return split.has(ident.id) && !a.panelDim
      ? labelKey(ident.label)
      : labelKey(a.panelDim);
  };
}

function majority<T>(xs: T[]): T | undefined {
  const counts = new Map<T, number>();
  for (const x of xs) counts.set(x, (counts.get(x) ?? 0) + 1);
  return [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
}

function guessDecimals(cells: IRCell[]): number {
  let max = 0;
  for (const c of cells) {
    const s = String(c.value);
    const dot = s.indexOf(".");
    if (dot >= 0) max = Math.max(max, Math.min(3, s.length - dot - 1));
  }
  return max;
}

function truncate(s: string, n: number): string {
  return s.length <= n ? s : s.slice(0, n - 1) + "…";
}

/** Measurement notes: the table headnote plus its applicable footnotes. */
export function measurementNotes(
  t: ManifestTable,
  m: ManifestMeasurement,
): string {
  return [
    t.headnote,
    ...m.footnoteMarkers.map((k) => `[${k}] ${t.footnotes[k]}`),
  ]
    .filter(Boolean)
    .join("\n");
}

/** All manifest series, flattened, with their measurement and table. */
export function allSeries(sections: ManifestSection[]) {
  return sections.flatMap((s) =>
    s.tables.flatMap((t) =>
      t.measurements.flatMap((m) =>
        m.series.map((series) => ({
          section: s,
          table: t,
          measurement: m,
          series,
        })),
      ),
    ),
  );
}
